import{_ as a,o as s,c as o,S as t}from"./chunks/framework.D1Ss-Xl7.js";const v=JSON.parse('{"title":"使用Postfix,Dovecot和Mysql配置邮件服务器","description":"由于学习的需要,我要配置个本地邮件服务器.虽然找到了一篇很详细的资料,但是在配置过程中还是遇到了这样那样的问题.\\n写篇文章记下来自己的学习过程,毕竟好记性不如烂笔头嘛.","frontmatter":{"title":"使用Postfix,Dovecot和Mysql配置邮件服务器","date":"2014-12-25 15:41","comments":true,"archives":2014,"tags":["notes"]},"headers":[],"relativePath":"posts/2014-12-25-configure-mail-server/index.md","filePath":"posts/2014/2014-12-25-Configure-Mail-Server.md"}'),n={name:"posts/2014-12-25-configure-mail-server/index.md"};function r(i,e,l,c,p,d){return s(),o("div",null,[...e[0]||(e[0]=[t(`<p>由于学习的需要,我要配置个本地邮件服务器.虽然找到了一篇很详细的资料,但是在配置过程中还是遇到了这样那样的问题. 写篇文章记下来自己的学习过程,毕竟好记性不如烂笔头嘛.</p><h2 id="详细教程" tabindex="-1">详细教程 <a class="header-anchor" href="#详细教程" aria-label="Permalink to &quot;详细教程&quot;">​</a></h2><p>Google 一下便找到了一个十分详细的教程,分享给大家:<a href="https://www.digitalocean.com/community/tutorials/how-to-configure-a-mail-server-using-postfix-dovecot-mysql-and-spamassasin" target="_blank" rel="noreferrer">How To Configure a Mail Server Using Postfix, Dovecot, MySQL, and SpamAssasin</a> 教程虽然很详细,但难免有不理解和差错的地方.下面就讲下我遇到的问题:</p><h2 id="dovecot-证书问题" tabindex="-1">Dovecot 证书问题 <a class="header-anchor" href="#dovecot-证书问题" aria-label="Permalink to &quot;Dovecot 证书问题&quot;">​</a></h2><p>教程上设置的证书位置是:</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span>ssl_cert = &lt;/etc/ssl/certs/dovecot.pem</span></span>
<span class="line"><span>ssl_key = &lt;/etc/ssl/private/dovecot.pem</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>但实际上是空的 需要手动 copy 过去,默认存储的位置是:</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span>ssl_cert = /etc/dovecot/dovecot.pem</span></span>
<span class="line"><span>ssl_key = /etc/dovecot/private/dovecot.pem</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><h2 id="查看日志发现读取配置出错" tabindex="-1">查看日志发现读取配置出错 <a class="header-anchor" href="#查看日志发现读取配置出错" aria-label="Permalink to &quot;查看日志发现读取配置出错&quot;">​</a></h2><p>出错信息如下:</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span>dovecot: lmtp(11504): Fatal: Error reading configuration: Invalid settings: postmaster_address setting not given</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>查到相关资料<a href="https://github.com/mail-in-a-box/mailinabox/issues/31" target="_blank" rel="noreferrer">Invalid settings: postmaster_address setting not given</a> 简单来说就是在<code>/etc/dovecot/dovecot.conf</code>文件内添加一行 <code>postmaster_address=postmaster at DOMAIN</code> 即可</p><h2 id="重启-dovecot" tabindex="-1">重启 Dovecot <a class="header-anchor" href="#重启-dovecot" aria-label="Permalink to &quot;重启 Dovecot&quot;">​</a></h2><p>当我们执行 <code>service dovecot restart</code> 时,发现根本没有这个 service.<br> 其实 dovecot 已经在运行了,我们只需执行 <code>dovecot reload</code> 即可</p><h2 id="邮件无法发送" tabindex="-1">邮件无法发送 <a class="header-anchor" href="#邮件无法发送" aria-label="Permalink to &quot;邮件无法发送&quot;">​</a></h2><p>日志输出如下:</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span>B0E4F26077E: to=&lt;root@example.jp&gt;, orig_to=&lt;root&gt;, relay=none, delay=6780, delays=6780/0/0.09/0, dsn=5.4.4, status=bounced (Host or domain name not found. Name service error for name=example.jp type=AAAA: Host not found)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>这个问题是因为 Postfix 默认启用了 IPv6 并且优先级比 IPv4 要高,所以需要在配置文件 <code>/etc/postfix/main.cf</code>里面设置 <code>inet_protocols = ipv4</code> 这样就关闭 IPv6 了.即可解决问题.</p><p>大概就是遇到这么多问题了,最后祝愿大家圣诞节快乐~</p>`,19)])])}const m=a(n,[["render",r]]);export{v as __pageData,m as default};
